// KotlinX memory manager interface (internal, stable). The runtime (compiler/runtime/runtime.c) and the
// code generated by newkotlinc call only the functions below; one implementation, compiler/gc/<name>/gc.c,
// is linked into every program (newkotlinc --gc=<name>, default "default"). It is compiled in the same
// clang -flto invocation as the runtime and the program, so the default implementation costs nothing extra.
//
// Object layout shared with the code generator (NativeBackend.kt):
//   word 0: header. Low 32 bits = reference count. For objects of possibly cyclic classes ("traced"
//           objects) bits 32-33 are a color and bit 34 a "buffered" flag owned by the implementation;
//           generated code only (a) sets the color to 3 when a decrement leaves a non-zero count and
//           calls rt_cc_possible_root unless the buffered bit is set, and (b) on a zero count releases
//           the fields and then frees the object with rt_free_trace unless the buffered bit is set
//           (then it clears the color to 0 and leaves the object to the implementation).
//           An implementation that never sets the buffered bit gets plain reference counting.
//   word 1: vtable pointer (KxVTab below).
// Retain / release fast paths are inlined by the code generator (Perceus: drop at last use, reuse,
// no RC for stack-allocated / immutable locals); only the slow paths below reach the implementation.
#ifndef KXGC_H
#define KXGC_H
#include <stddef.h>
#include <stdint.h>

typedef void (*kx_visit_fn)(void *);
/* vtable prefix of every class: release, trace traced children, release untraced fields, free memory, is-cyclic. */
typedef struct {
    void (*rel)(void *);                /* drop one reference (decrement; at zero release fields and free) */
    void (*trav)(void *, kx_visit_fn);  /* call visit on every reference field (may be NULL children) */
    void (*relo)(void *);               /* release fields the collector does not trace (acyclic, lists...) */
    void (*freemem)(void *);            /* return the object's memory; fields must already be released */
    void *cyclic;                       /* non-NULL iff the class is possibly cyclic (traced) */
} KxVTab;

/* Header word bits (see layout above). Color values: compiler/gc/common/object.inc. */
#define KX_CNT_MASK 0xffffffffULL       /* reference count: bits 0-31 */
#define KX_COLOR_SHIFT 32               /* color: bits 32-33 */
#define KX_BUF_BIT (1ULL << 34)         /* in the collector's root buffer */

// ---- objects ----
void *rt_alloc(int64_t size);                 /* acyclic object (count 1 set by caller) */
void rt_free(void *p, int64_t size);          /* acyclic object whose count reached zero */
void *rt_alloc_trace(int64_t size);           /* possibly cyclic object */
void rt_free_trace(void *p, int64_t size);    /* possibly cyclic object whose count reached zero */
void rt_cc_possible_root(void *p);            /* traced object decremented to a non-zero count */
void rt_cc_dead(void *p);                     /* traced object at zero count, fields already released */

// ---- deferred RC (only called by code generated for GCs with the "deferred" capability, e.g. epoch) ----
void rt_gc_log_inc(void *p);                  /* retain of a traced object */
void rt_gc_log_dec(void *p);                  /* release of a traced object */
void rt_gc_write_barrier(void *obj);          /* after a reference store into a field of traced obj */

// ---- runtime memory that may hold object references (ArrayList storage, HashMap values, arrays) ----
void *rt_gc_mem_alloc(size_t n);
void *rt_gc_mem_calloc(size_t n);             /* zeroed */
void *rt_gc_mem_realloc(void *p, size_t n);
void rt_gc_mem_free(void *p);

// ---- lifecycle, collection, statistics ----
void rt_gc_collect(void);                     /* full collection; also run at program exit */
const char *rt_gc_name(void);
typedef struct {
    int64_t collections;                      /* collector runs */
    int64_t reclaimed;                        /* objects reclaimed by the collector (not by RC) */
    int64_t pause_ns_total, pause_ns_max;     /* time spent in the collector */
} KxGcStats;
void rt_gc_stats(KxGcStats *out);

// ---- provided by the runtime ----
void rt_panic(const char *msg) __attribute__((noreturn));
int64_t rt_nanos(void);
/* Non-zero while the runtime releases objects that a deep release deferred (rt_rel_defer). They sit at count
 * zero with their fields unreleased, as no object does in a collection, where a release runs to the end
 * before the next step: a buffered one would pass for dead. A collection must not start meanwhile. */
extern int rt_rel_draining;
#ifdef RT_LEAKCHECK
void rt_leak_obj(int64_t d);                  /* live object counter for --leak-check */
#endif
#endif
